const std=@import("std");const V=@import("combined_view.zig");
const P=struct{worldMode:enum{sandbox,origin}=.origin,landBeta:@import("simulation/land_beta.zig").Config=.{},windDispersal:@import("simulation/wind_genetics.zig").Config=.{},protectiveStrategy:@import("simulation/protective_strategy.zig").Config=.{},groundThermalLaw:u8=0};
test "unified writer identity preserves standalone and combined without conversion"{
 var s=struct{planet:P=.{}}{};try std.testing.expectEqual(@as(u32,7),V.writerVersion(&s));s.planet.windDispersal=.{.enabled=true,.law=1,.stream_seed=42};try std.testing.expectEqual(@as(u32,11),V.writerVersion(&s));const before=s;const raw=V.snapshot(@as(?*@TypeOf(s),&s),4);try std.testing.expect(std.mem.indexOf(u8,std.mem.span(raw),"\"status\":\"wind\"")!=null);try std.testing.expectEqualDeep(before,s);
 s.planet.groundThermalLaw=1;try std.testing.expectEqual(@as(u32,0),V.writerVersion(&s));s.planet.groundThermalLaw=0;s.planet.landBeta=.{.enabled=true,.law=1,.physiology_law=3,.root_mutation=.{.enabled=true,.law=1,.stream_seed=42}};try std.testing.expectEqual(@as(u32,13),V.writerVersion(&s));s.planet.groundThermalLaw=1;try std.testing.expectEqual(@as(u32,14),V.writerVersion(&s));s.planet.protectiveStrategy=.{.enabled=true,.law=1,.mutation_law=1,.stream_seed=42};try std.testing.expectEqual(@as(u32,15),V.writerVersion(&s));s.planet.worldMode=.sandbox;try std.testing.expectEqual(@as(u32,0),V.writerVersion(&s));
}
